await scene('timeout',async c=>{
  c.setStatus('hold');const s=c.sender({timeoutMs:25,maxRetries:0});s.enqueue({eventId:'timeout'});await s.flush();assert.equal(c.requests.length,1);await until(()=>c.pending[0].destroyed,'abort closes response before driver cleanup');c.trace.push({metrics:s.snapshot(),responseClosedBeforeCleanup:true});assert.equal(s.snapshot().dropped,1);await s.shutdown();
});
await scene('gateway-observer',async c=>{
  const collector=c.collector(),observer=new GatewayAgentEventTelemetryObserver({telemetry:collector}),resolver=new GatewayTurnTelemetryContextResolver();const context={sessionId:'session',runId:'run',channelKey:'web',permissionMode:'default',ownerModule:'memory',executionKind:'user_session',phase:'phase'};
  const events=[{type:'model_request_started'},{type:'model_event',event:{type:'request_started',provider:'p',model:'m',providerBaseUrl:'http://example.invalid/v1'}},{type:'model_event',event:{type:'message_end'}},{type:'model_event',event:{type:'error',error:{code:'bad_model',provider:'p'}}},{type:'tool_calls_detected',calls:[{name:'bash'},{name:'read_file'}]},{type:'pre_tool_execute',toolName:'bash',toolCallId:'tc'},{type:'post_tool_execute',toolName:'bash',toolCallId:'tc',success:false},...['invalid_argument','json_decode','other'].map(code=>({type:'tool_result',result:{type:'error',toolName:'bash',toolCallId:'tc',error:{code,message:'private'}}})),{type:'permission_requested',toolName:'bash',toolCallId:'tc'},{type:'permission_denied',toolName:'bash',reason:'private'},{type:'turn_completed',result:{stopReason:'done',turns:2}},{type:'turn_failed',error:{code:'loop_bad'}},{type:'session_aborted',reason:'abort'},...['request_started','message_end','error'].map(type=>({type:'subagent_model_event',subagentId:'sub',subagentType:'test',event:{type,provider:'p',model:'m',error:{code:'sub_bad',provider:'p'}}})),{type:'subagent_tool_calls_detected',subagentId:'sub',subagentType:'test',calls:[{name:'tool'}]},{type:'subagent_tool_result',subagentId:'sub',subagentType:'test',result:{type:'error',toolName:'tool',toolCallId:'subtc',error:{code:'schema',message:'private'}}},{type:'subagent_tool_result',subagentId:'sub',subagentType:'test',result:{type:'text',toolName:'tool',toolCallId:'subtc'}},{type:'assistant_text_delta',text:'never telemetered'}];for(const event of events)observer.observe(event,context);await collector.flush();checkEvents(c.requests);assert.equal(c.requests[0].body.length,28);c.trace.push({inputs:events,context,resolved:[{channelKey:'web'},{channelKey:'always-on/daily',telemetry:{phase:'other'}},{channelKey:'always-on/',telemetry:{phase:'fallback',ownerModule:'memory'}},{channelKey:'always-on/daily',telemetry:{ownerModule:'cron_job',executionKind:'cron_job',phase:'explicit'}}].map(input=>({input,value:resolver.resolve(input)})),metrics:collector.snapshot()});await collector.shutdown();
});
await scene('registry',async c=>{
  const logs=[],failures=[],oldGate=gate(),registry=new TelemetryObserverRegistry({onObserverFailure:f=>{failures.push({name:f.name,generation:f.generation,message:f.error.message});throw Error('diagnostic ignored');}});
  const old=registry.register(' old ',{observe:o=>{logs.push(['old',o.type]);return oldGate.promise;},dispose:()=>logs.push(['disposed','old'])});registry.register('broken',{observe:()=>{throw Error('observer failed');},dispose:()=>logs.push(['disposed','broken'])});
  const base=c.collector(),client=createObservingTelemetryClient(base,registry);client.trackError(new TypeError('private'),{module:'session'});assert.equal(old.inFlight,1);const replacement=registry.replace('old',{observe:o=>logs.push(['new',o.type]),dispose:()=>logs.push(['disposed','new'])});assert.equal(replacement.registration.generation,3);assert.equal(old.state,'draining');client.trackFeatureUsed({module:'memory',loopStage:'module_event'});assert.equal(old.inFlight,1);const closing=registry.dispose();assert.equal(registry.state,'draining');client.track('feature_used',{after:'dispose'});oldGate.resolve();await replacement.previousDisposed;await closing;assert.equal(registry.state,'disposed');assert.equal(registry.size,0);await client.flush();checkEvents(c.requests);assert.equal(c.requests[0].body.length,4);c.trace.push({logs,failures,metrics:client.snapshot()});await client.shutdown();
});
